from collections import defaultdict, deque
import sys

def read_ints():
    return list(map(int, sys.stdin.readline().strip().split()))

def main():
    t = int(sys.stdin.readline().strip())
    for _ in range(t):
        n = int(sys.stdin.readline().strip())
        edges = defaultdict(list)
        for _ in range(n - 1):
            u, v = read_ints()
            edges[u].append(v)
            edges[v].append(u)

        # Count the number of leaves initially
        leaves = 0
        for i in range(1, n + 1):
            if len(edges[i]) == 1:
                leaves += 1

        # The minimum number of leaves is the number of buds
        # Since each bud can be moved to the root
        print(max(1, leaves))

if __name__ == "__main__":
    main()
